export type SubmissionState = "pending" | "accepted" | "declined";

export interface SubmissionInput {
  title: string;
  author: string;
  tags: readonly string[];
}

export interface Submission extends SubmissionInput {
  id: string;
  state: SubmissionState;
}

export interface SubmissionReport {
  total: number;
  submissions: Submission[];
}

export class SubmissionDesk {
  private nextId = 1;
  private readonly entries: Submission[] = [];

  create(input: SubmissionInput): Submission {
    const title = input.title.trim();
    const author = input.author.trim();
    const tags = input.tags.map((tag) => tag.trim());
    if (title.length === 0 || author.length === 0 || tags.some((tag) => tag.length === 0)) {
      throw new RangeError("Submission fields must be non-blank");
    }
    const entry: Submission = {
      id: `S${this.nextId++}`,
      title,
      author,
      tags,
      state: "pending",
    };
    this.entries.push(entry);
    return this.copy(entry);
  }

  setState(id: string, state: SubmissionState): Submission {
    const normalizedId = id.trim();
    if (normalizedId.length === 0) throw new RangeError("ID must be non-blank");
    const entry = this.entries.find((candidate) => candidate.id === normalizedId);
    if (!entry) throw new Error(`Unknown submission: ${normalizedId}`);
    if (entry.state === state) return this.copy(entry);
    if (entry.state === "pending") throw new Error("Invalid state transition");
    entry.state = state;
    return this.copy(entry);
  }

  report(): SubmissionReport {
    return { total: this.entries.length, submissions: this.entries.map((entry) => this.copy(entry)) };
  }

  private copy(entry: Submission): Submission {
    return { ...entry, tags: [...entry.tags] };
  }
}

