import { SubmissionDesk } from "./solution";
import type { SubmissionState, SubmissionInput, Submission, SubmissionReport } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function expectError(action: () => void, constructor: typeof Error, message?: string): void {
  let thrown: unknown;
  try { action(); } catch (error) { thrown = error; }
  assert(thrown instanceof constructor, `expected ${constructor.name}`);
  if (message !== undefined && thrown.message !== message) throw new Error(`expected ${message}, got ${thrown.message}`);
}

const pending: SubmissionState = "pending";
const desk = new SubmissionDesk();
let report: SubmissionReport = desk.report();
equal(report.total, 0, "new desk total");
equal(report.submissions.length, 0, "new desk submissions");

const tags = [" ts ", "behavior"];
const input: SubmissionInput = { title: " First ", author: " Ada ", tags };
const first: Submission = desk.create(input);
equal(first.id, "S1", "first ID");
equal(first.title, "First", "title normalized");
equal(first.author, "Ada", "author normalized");
equal(first.state, pending, "initial state");
equal(first.tags[0], "ts", "tags normalized");
tags[0] = "changed";
(input as { title: string }).title = "changed";
(first as { title: string }).title = "external";
(first.tags as string[])[0] = "external";

expectError(() => desk.create({ title: " ", author: "A", tags: [] }), RangeError);
expectError(() => desk.create({ title: "T", author: "\t", tags: [] }), RangeError);
expectError(() => desk.create({ title: "T", author: "A", tags: ["ok", " "] }), RangeError);
const second = desk.create({ title: "Second", author: "Bob", tags: [] });
equal(second.id, "S2", "invalid creates do not consume IDs");

report = desk.report();
equal(report.total, 2, "report total");
equal(report.submissions[0].id, "S1", "creation order retained");
equal(report.submissions[0].title, "First", "returned submission was defensive");
equal(report.submissions[0].tags[0], "ts", "returned tags were defensive");
equal(report.submissions[1].id, "S2", "second report item");

(report as { total: number }).total = 99;
(report.submissions as Submission[]).reverse();
(report.submissions[0] as { author: string }).author = "mutated";
const fresh = desk.report();
equal(fresh.total, 2, "report object is independent");
equal(fresh.submissions[0].id, "S1", "report array is independent");
equal(fresh.submissions[1].author, "Bob", "report entries are independent");

desk.setState(" S1 ", "accepted");
desk.setState("S1", "accepted");
equal(desk.report().submissions[0].state, "accepted", "accepted state stored");
expectError(() => desk.setState("S1", "declined"), Error, "Invalid state transition");
desk.setState("S2", "declined");
equal(desk.report().submissions[1].state, "declined", "pending can decline");
expectError(() => desk.setState(" ", "accepted"), RangeError);
expectError(() => desk.setState(" missing ", "accepted"), Error, "Unknown submission: missing");

